from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bh, bw = h // 3, w // 3
    out = []
    for bi in range(bh):
        row = []
        for bj in range(bw):
            counts = Counter(
                grid[r][c]
                for r in range(bi * 3, bi * 3 + 3)
                for c in range(bj * 3, bj * 3 + 3)
                if grid[r][c] != 5
            )
            row.append(counts.most_common(1)[0][0])
        out.append(row)
    return out
